  function subjectLabel(s){const bn={'Physics':'পদার্থবিজ্ঞান','Chemistry':'রসায়ন','Higher Mathematics':'উচ্চতর গণিত','Biology':'জীববিজ্ঞান','ICT':'তথ্য ও যোগাযোগ প্রযুক্তি','Bangla':'বাংলা','English':'ইংরেজি','Accounting':'হিসাববিজ্ঞান','Finance, Banking & Insurance':'ফিন্যান্স, ব্যাংকিং ও বিমা','Business Organization & Management':'ব্যবসায় সংগঠন ও ব্যবস্থাপনা','Economics':'অর্থনীতি','Sociology':'সমাজবিজ্ঞান','Civics & Good Governance':'পৌরনীতি ও সুশাসন','Logic':'যুক্তিবিদ্যা','History':'ইতিহাস'};return lang==='bn'?(bn[s]||s):s;}
  function subjectOptions(){return subjects.map(s=>`<option value="${esc(s)}">${esc(subjectLabel(s))}</option>`).join('');}
