  function renderGoogleProfile(profile){googlePendingProfile=profile;showAuthGate();$('#gate-tabs').classList.add('hidden');$('#gate-eyebrow').textContent='GOOGLE ACCOUNT CONNECTED';$('#gate-title').textContent=lang==='bn'?'প্রোফাইল সম্পূর্ণ করো':'Complete your profile';$('#gate-subtitle').textContent=lang==='bn'?'তোমার HSC শ্রেণি ও বিভাগ জানলেই অ্যাকাউন্ট তৈরি সম্পূর্ণ হবে।':'Choose your HSC class and group to finish creating your account.';$('#gate-form-slot').innerHTML=`<div class="google-profile-chip"><span class="google-profile-avatar">${esc(initials(profile.display_name))}</span><div><b>${esc(profile.display_name)}</b><small>${esc(profile.email)}</small></div></div><form id="google-pending-form" class="gate-form"><div class="form-row"><label><span>${lang==='bn'?'শ্রেণি':'Class'}</span><select name="class_name" required><option>Class XI</option><option>Class XII</option></select></label><label><span>${lang==='bn'?'বিভাগ':'Group'}</span><select name="study_group"><option value="Science">${lang==='bn'?'বিজ্ঞান':'Science'}</option><option value="Humanities">${lang==='bn'?'মানবিক':'Humanities'}</option><option value="Business Studies">${lang==='bn'?'ব্যবসায় শিক্ষা':'Business Studies'}</option></select></label></div><div class="form-row"><label><span>${lang==='bn'?'শিক্ষা বোর্ড':'Education board'}</span><select name="education_board" required>${boardSelect('Dhaka')}</select></label><label><span>${lang==='bn'?'পছন্দের ভাষা':'Preferred language'}</span><select name="preferred_language"><option value="bn">বাংলা</option><option value="en">English</option></select></label></div><label class="gate-consent"><input type="checkbox" name="agree_terms" required><span>${lang==='bn'?'আমি কমিউনিটি গাইডলাইন ও গোপনীয়তা নীতি মেনে চলতে সম্মত।':'I agree to the community guidelines and privacy notice.'}</span></label><button class="primary-button full-button gate-submit" type="submit">${lang==='bn'?'অ্যাকাউন্ট সম্পূর্ণ করো':'Finish account setup'} ↗</button></form>`;$('#google-auth-btn').classList.add('hidden');$('#google-hint').classList.add('hidden');$('#gate-separator').classList.add('hidden');}
  function showOnboarding(){const html=`<form id="onboarding-form" class="modal-form survey-form"><div class="survey-intro"><span class="survey-spark">✦</span><p>${lang==='bn'?'তোমার প্রয়োজন বুঝে AJZIO Education-কে আরও ভালো করতে কয়েকটি ছোট প্রশ্ন।':'A few quick questions help us make AJZIO Education more useful for you.'}</p></div><label>${lang==='bn'?'১. পড়াশোনায় তোমার প্রধান লক্ষ্য কী?':'1. What is your main learning goal?'}<select name="learning_goal" required><option value="board_exam">${lang==='bn'?'বোর্ড পরীক্ষায় ভালো প্রস্তুতি':'Prepare for board exams'}</option><option value="concepts">${lang==='bn'?'কঠিন বিষয় বুঝে শেখা':'Understand difficult concepts'}</option><option value="practice">${lang==='bn'?'নিয়মিত পরীক্ষা ও অনুশীলন':'Regular tests and practice'}</option><option value="resources">${lang==='bn'?'ভালো নোট ও রিসোর্স পাওয়া':'Find quality notes and resources'}</option><option value="self_study">${lang==='bn'?'নিজের পড়াশোনা নিজে গুছিয়ে নেওয়া':'Organize independent study'}</option></select></label><label>${lang==='bn'?'২. এখন তোমার সবচেয়ে বড় সমস্যা কোনটি?':'2. What is your biggest study challenge?'}<select name="biggest_challenge" required><option value="quality_notes">${lang==='bn'?'ভালো মানের নোট খুঁজে পাওয়া':'Finding quality notes'}</option><option value="hard_topics">${lang==='bn'?'কঠিন অধ্যায় বুঝতে সমস্যা':'Understanding difficult topics'}</option><option value="exam_fear">${lang==='bn'?'পরীক্ষার অনুশীলন কম':'Not enough exam practice'}</option><option value="time_management">${lang==='bn'?'সময় ও রুটিন ম্যানেজ করা':'Managing time and routine'}</option><option value="study_plan">${lang==='bn'?'কীভাবে পড়ব বুঝতে না পারা':'Not knowing how to study'}</option><option value="other">${lang==='bn'?'অন্যান্য':'Other'}</option></select></label><fieldset class="survey-features"><legend>${lang==='bn'?'৩. কোন সুবিধাগুলো বেশি দরকার? (একাধিক বেছে নিতে পারো)':'3. Which features would help you most? (Choose any)'}</legend>${[['notes','নোট লাইব্রেরি','Notes library'],['exams','সাপ্তাহিক পরীক্ষা','Weekly exams'],['question_bank','প্রশ্নব্যাংক','Question bank'],['study_planner','স্টাডি প্ল্যানার','Study planner'],['community','প্রশ্নোত্তর কমিউনিটি','Student community']].map(x=>`<label><input type="checkbox" name="preferred_features" value="${x[0]}"><span>${lang==='bn'?x[1]:x[2]}</span></label>`).join('')}</fieldset><label>${lang==='bn'?'আর কী যোগ বা পরিবর্তন করলে ভালো হবে? (ঐচ্ছিক)':'What else should we add or improve? (Optional)'}<textarea name="improvement_text" rows="3" maxlength="1000" placeholder="${lang==='bn'?'তোমার আইডিয়া লিখো...':'Share your idea...'}"></textarea></label><div class="survey-actions"><button type="button" class="subtle-link" id="survey-skip">${lang==='bn'?'এখন নয়':'Maybe later'}</button><button class="primary-button" type="submit">${lang==='bn'?'উত্তর জমা দাও':'Submit answers'} →</button></div></form>`;openModal(lang==='bn'?'তোমার কাছ থেকে জানতে চাই':'Help us learn about you','A QUICK WELCOME SURVEY',html);}
  function accountIsRestricted(user){return !!user&&(user.account_status==='locked'||(user.account_status==='suspended'&&user.suspended_until&&new Date(user.suspended_until).getTime()>Date.now()));}
  async function renderRestrictionPage(user){
    me=user;clearInterval(chatRefreshTimer);chatRefreshTimer=null;$('#auth-gate').classList.add('hidden');$('#app-shell').classList.add('hidden');$('#restriction-gate').classList.remove('hidden');document.body.classList.add('signed-out');
    const locked=user.account_status==='locked';$('#restriction-message').textContent=locked?(lang==='bn'?'অ্যাডমিন তোমার অ্যাকাউন্টটি লক করেছেন। নিচের ফর্মে কারণ ব্যাখ্যা করে আপিল পাঠাতে পারো।':'An administrator has locked this account. Use the form below to request a review.'):(lang==='bn'?'কমিউনিটি নিরাপত্তা নীতির কারণে তোমার অ্যাকাউন্ট সাময়িকভাবে স্থগিত।':'Your account is temporarily suspended under the community safety rules.');
    let appeal=null;try{appeal=(await api('/appeal')).appeal;}catch(_){ }
    const until=user.suspended_until?new Date(user.suspended_until).toLocaleString(lang==='bn'?'bn-BD':'en-GB'):(lang==='bn'?'অ্যাডমিন পর্যালোচনা পর্যন্ত':'Until admin review');
    $('#restriction-status').innerHTML=`<div><b>${locked?(lang==='bn'?'অ্যাকাউন্ট লক':'Account locked'):(lang==='bn'?'সাময়িক স্থগিত':'Temporary suspension')}</b></div><div>${esc(user.restriction_reason||'Community safety review')}</div><div>${lang==='bn'?'সময় / অবস্থা: ':'Until / status: '}${esc(until)}</div><div>${lang==='bn'?'AJZIO ID: ':'AJZIO ID: '}#${esc(user.member_no||'—')}</div>`;
    if(appeal){const label={pending:lang==='bn'?'আপিল জমা হয়েছে; অ্যাডমিন পর্যালোচনা করবেন।':'Appeal submitted; the administrator will review it.',approved:lang==='bn'?'আপিল অনুমোদিত হয়েছে। পেজ রিফ্রেশ করে আবার চেষ্টা করো।':'Appeal approved. Refresh and sign in again.',declined:lang==='bn'?'আপিল গ্রহণ করা হয়নি। প্রয়োজনে নতুন ব্যাখ্যাসহ আবার আপিল করতে পারো।':'Appeal declined. You may submit a new explanation.'}[appeal.status]||appeal.status;$('#restriction-appeal-slot').innerHTML=`<div class="appeal-state"><b>${esc(label)}</b>${appeal.admin_response?`<p>${esc(appeal.admin_response)}</p>`:''}</div>${appeal.status==='declined'?restrictionAppealForm():''}`;}
    else $('#restriction-appeal-slot').innerHTML=restrictionAppealForm();
  }
  function restrictionAppealForm(){return `<form id="restriction-appeal-form" class="restriction-form"><label>${lang==='bn'?'আপিলের কারণ (৩০–১৫০০ অক্ষর)':'Explain your appeal (30–1500 characters)'}<textarea name="details" minlength="30" maxlength="1500" required placeholder="${lang==='bn'?'ঘটনাটি ব্যাখ্যা করো এবং কেন সিদ্ধান্তটি পুনর্বিবেচনা করা উচিত জানাও…':'Explain what happened and why the decision should be reviewed…'}"></textarea></label><button class="primary-button" type="submit">${lang==='bn'?'আপিল জমা দাও':'Submit appeal'} →</button></form>`;}
  async function enterApp(user, showSurvey=true){me=user;if(accountIsRestricted(user)){await renderRestrictionPage(user);return;}$('#restriction-gate').classList.add('hidden');showApp();applyLanguage();updateUser();await loadHome();if(showSurvey&&me&&!me.survey_completed)showOnboarding();}
  function updateUser(){const signed=!!me;$('#auth-open').classList.toggle('hidden',signed);$('#top-user').classList.toggle('hidden',!signed);$('#admin-nav').classList.toggle('hidden',!me||!['admin','moderator'].includes(me.role));$('#owner-admin-nav').classList.toggle('hidden',!me||me.role!=='admin');const name=me?.display_name||tx('guest');$('#welcome-name').textContent=name;$('#sidebar-name').textContent=name;$('#sidebar-role').textContent=me?`#${me.member_no||'—'} · ${me.class_name} · ${me.study_group}`:tx('notSigned');$('#sidebar-avatar').innerHTML=me?.avatar_file?`<img class="sidebar-avatar-image" src="/api/profile/avatar/${me.member_no}" alt="">`:esc(initials(name));$('#top-user').textContent=initials(name);$('#welcome-greeting').textContent=lang==='bn'?(me?'আবার স্বাগতম':'স্বাগতম'):(me?'Welcome back':'Welcome');}
  async function loadStats(){stats=await api('/stats');$('#stat-notes').textContent=stats.approved_notes;$('#stat-students').textContent=stats.students;$('#stat-exams').textContent=stats.exams;$('#stat-requests').textContent=stats.requests;$('#nav-note-count').textContent=stats.approved_notes;}
  function noteCard(n){const author=esc(n.author_name);return `<article class="note-card"><div class="note-card-top"><span class="subject-icon ${subjectClass(n.subject)}">${esc(subjectGlyph(n.subject))}</span><span class="verified-badge">✓ ${tx('verified')}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.description||n.chapter)}</p><div class="note-meta"><span>${esc(subjectLabel(n.subject))}</span><span>${esc(n.chapter)}</span><span>${n.content_language==='bn'?'বাংলা':'English'}</span></div><div class="note-card-footer"><span class="note-author"><i class="mini-avatar">${esc(initials(author))}</i>${author}</span><button class="note-open" data-note="${esc(n.id)}">${lang==='bn'?'দেখো →':'View →'}</button></div></article>`;}
  async function loadHome(){try{await loadStats();const d=await api('/notes');$('#featured-notes').innerHTML=d.notes.slice(0,3).map(noteCard).join('')||`<div class="empty-state">${tx('noNotes')}</div>`;}catch(e){toast(e.message,true);}}
  async function loadNotes(){const q=$('#note-search').value.trim();const subject=$('#subject-filter').value;const qs=new URLSearchParams();if(q)qs.set('q',q);if(subject)qs.set('subject',subject);try{const d=await api('/notes?'+qs.toString());$('#all-notes').innerHTML=d.notes.map(noteCard).join('')||`<div class="empty-state">${tx('noNotes')}</div>`;$('#note-count-label').textContent=lang==='bn'?`${d.notes.length}টি নোট`:`${d.notes.length} notes`;}catch(e){$('#all-notes').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`;}}
  async function loadExams(){try{const [d,summary]=await Promise.all([api('/exams'),me?api('/my/summary'):Promise.resolve({exam_points:0})]);examsCache=d.exams;$('#exam-points').textContent=summary.exam_points||0;$('#exam-list').innerHTML=d.exams.map(e=>{const now=Date.now(),opens=e.opens_at?new Date(e.opens_at).getTime():0,closes=e.closes_at?new Date(e.closes_at).getTime():0;const wrongClass=e.class_name!=='All HSC'&&me&&e.class_name!==me.class_name;const wrongGroup=e.study_group!=='All'&&me&&e.study_group!==me.study_group;const scheduled=opens&&now<opens;const closed=closes&&now>closes;const locked=Boolean(wrongClass||wrongGroup||scheduled||closed||e.attempted);const status=e.attempted?(lang==='bn'?'সম্পন্ন':'Completed'):scheduled?(lang==='bn'?'পরীক্ষা শুরু হবে':'Scheduled'):closed?(lang==='bn'?'সময় শেষ':'Closed'):(wrongClass||wrongGroup)?(lang==='bn'?'তোমার জন্য নয়':'Not assigned'):(lang==='bn'?'প্রকাশিত':'Published');const action=e.attempted?status:scheduled?(lang==='bn'?`শুরু ${dateText(e.opens_at)}`:`Opens ${dateText(e.opens_at)}`):closed?status:(wrongClass||wrongGroup)?status:tx('start')+' →';return `<article class="exam-card"><div class="exam-card-icon">${esc(subjectGlyph(e.subject))}</div><div class="exam-card-main"><h3>${esc(e.title)}</h3><p>${esc(subjectLabel(e.subject))} · ${esc(e.chapter)}</p><div class="exam-meta"><span>◷ ${e.duration_minutes} ${lang==='bn'?'মিনিট':'min'}</span><span>${e.question_count} ${lang==='bn'?'প্রশ্ন':'questions'}</span><span>${esc(e.class_name)} · ${esc(e.study_group)}</span></div></div><span class="status-chip">${status}</span><button class="exam-action" data-exam="${esc(e.id)}" ${locked?'disabled':''}>${action}</button></article>`;}).join('')||`<div class="empty-state">${tx('emptyExam')}</div>`;}catch(e){$('#exam-list').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`;}}
  async function startExam(id){if(!me){authOpen();return;}try{const d=await api(`/exams/${encodeURIComponent(id)}/start`,{method:'POST',body:'{}'});activeExam={...d.exam,questions:d.questions,session_id:d.session_id};examStartedAt=d.started_at;const mins=d.exam.duration_minutes;const html=`<div class="timer-chip"><span>${esc(d.exam.subject)} · ${esc(d.exam.chapter)}</span><b id="exam-timer">${mins}:00</b></div><form id="take-exam-form">${d.questions.map((q,i)=>`<div class="question-block"><small>QUESTION ${i+1} / ${d.questions.length} · ${q.points} ${lang==='bn'?'পয়েন্ট':'pt'}</small><h3>${esc(q.prompt)}</h3>${[q.option_a,q.option_b,q.option_c,q.option_d].map((op,j)=>`<label class="answer-choice"><input type="radio" name="${esc(q.id)}" value="${j}" required><span>${String.fromCharCode(65+j)}.</span>${esc(op)}</label>`).join('')}</div>`).join('')}<p class="form-footnote">${lang==='bn'?'সময় শেষ হলে স্বয়ংক্রিয়ভাবে জমা হবে। একবারই পরীক্ষা দেওয়া যাবে।':'The exam is submitted automatically when time expires. Only one attempt is allowed.'}</p><button class="primary-button full-button" type="submit">${tx('submitExam')} →</button></form>`;openModal(d.exam.title,'WEEKLY EXAMINATION',html);let left=Math.max(0,Math.floor((new Date(d.started_at).getTime()+mins*60000-Date.now())/1000));const firstTimer=$('#exam-timer');if(firstTimer)firstTimer.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;timerInterval=setInterval(()=>{left--;const t=$('#exam-timer');if(t)t.textContent=`${Math.floor(Math.max(0,left)/60)}:${String(Math.max(0,left)%60).padStart(2,'0')}`;if(left<=0){clearInterval(timerInterval);submitExam(true);}},1000);}catch(e){toast(e.message,true);}}
  async function submitExam(auto=false){if(!activeExam)return;const form=$('#take-exam-form');if(!form)return;const data=new FormData(form);const answers={};for(const q of activeExam.questions){const v=data.get(q.id);if(v===null){if(auto){answers[q.id]=-1;continue;}toast(tx('answerAll'),true);return;}answers[q.id]=Number(v);}if(Object.keys(answers).length!==activeExam.questions.length&&!auto){toast(tx('answerAll'),true);return;}clearInterval(timerInterval);try{const result=await api(`/exams/${encodeURIComponent(activeExam.id)}`,{method:'POST',body:JSON.stringify({answers,session_id:activeExam.session_id})});showResult(result);}catch(e){toast(e.message,true);}}
  function showResult(r){const pct=Math.round(r.score/Math.max(1,r.max_score)*100);const rows=r.answers.map((a,i)=>`<div class="explanation"><b class="${a.is_correct?'correct-text':'wrong-text'}">${a.is_correct?'✓':'✕'} ${esc(a.prompt)}</b><p>${tx('correct')}: <strong>${String.fromCharCode(65+a.correct_option)}. ${esc(a.options[a.correct_option])}</strong></p>${!a.is_correct?`<p>${tx('incorrect')}: ${a.selected_option<0?'—':String.fromCharCode(65+a.selected_option)+'. '+esc(a.options[a.selected_option])}</p>`:''}<p><strong>${tx('explanation')}:</strong> ${esc(a.explanation)}</p></div>`).join('');openModal(tx('yourResult'),'RESULT & EXPLANATIONS',`<div class="result-score"><b>${r.score} / ${r.max_score}</b><span>${pct}% · ${lang==='bn'?'তোমার ফলাফল সার্ভারে সংরক্ষিত হয়েছে':'Your result has been saved on the server'}</span></div>${rows}<button class="primary-button full-button" id="result-done">${lang==='bn'?'সম্পন্ন':'Done'}</button>`);$('#result-done').addEventListener('click',()=>{closeModal();loadExams();loadStats();});}
  function uploadModal(){if(!me){authOpen();return;}openModal(tx('uploadTitle'),'COMMUNITY CONTRIBUTION',`<form id="upload-form" class="modal-form"><label>${tx('noteTitle')}<input name="title" maxlength="120" required></label><div class="form-row"><label>${tx('subject')}<select name="subject" required>${subjectOptions()}</select></label><label>${tx('paper')}<input name="paper" maxlength="40" placeholder="1st / 2nd paper"></label></div><label>${tx('chapter')}<input name="chapter" maxlength="100" required></label><div class="form-row"><label>${tx('type')}<select name="note_type"><option>Chapter Summary</option><option>Detailed Notes</option><option>Short Notes</option><option>Formula Sheet</option><option>Question Solution</option></select></label><label>${tx('language')}<select name="content_language"><option value="bn">বাংলা</option><option value="en">English</option></select></label></div><label>${tx('description')}<textarea name="description" rows="3" maxlength="500"></textarea></label><label class="upload-box">⇧ <b>${tx('file')}</b><small>${tx('uploadHelp')}</small><input name="file" type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required></label><label class="consent-row"><input type="checkbox" name="permission_agree" value="yes" required><span>${lang==='bn'?'আমি নোটটির মালিক অথবা শেয়ার করার অনুমতি পেয়েছি। AJZIO Education-এ এটি অন্য শিক্ষার্থীদের জন্য বিনামূল্যে দেখানো ও ডাউনলোডের অনুমতি দিচ্ছি।':'I own this note or have permission to share it, and allow AJZIO Education to display and distribute it free for student learning.'}</span></label><p class="form-footnote">${tx('copyright')}</p><button type="submit" class="primary-button full-button">${tx('submit')} →</button></form>`);}
  async function handleUpload(form){const fd=new FormData(form);const f=fd.get('file');if(f&&f.size>10*1024*1024){toast(tx('uploadHelp'),true);return;}fd.set('class_name',me.class_name);fd.set('study_group',me.study_group);try{await api('/notes',{method:'POST',body:fd});closeModal();toast(lang==='bn'?'নোট জমা হয়েছে। যাচাইয়ের পর প্রকাশিত হবে।':'Note submitted. It will be published after review.');loadMyNotes();loadActivity();}catch(e){toast(e.message,true);}}
  async function noteDetail(id){try{const d=await api('/notes');const n=d.notes.find(x=>x.id===id);if(!n)return;const file=n.file_id?`<a class="file-open" href="${API}/files/${encodeURIComponent(n.file_id)}" target="_blank" rel="noopener">↓ ${tx('download')}</a>`:'';const html=`<div class="note-detail-meta"><span>${esc(subjectLabel(n.subject))}</span><span>${esc(n.chapter)}</span><span>${n.content_language==='bn'?'বাংলা':'English'}</span></div><p class="note-detail-desc">${esc(n.description||n.chapter)}</p><p class="form-footnote">${tx('by')} ${esc(n.author_name)} · ${dateText(n.created_at)}</p>${file}<form id="feedback-form" class="modal-form"><label>${tx('rate')}<select name="rating"><option value="5">5 — ★★★★★</option><option value="4">4 — ★★★★</option><option value="3">3 — ★★★</option><option value="2">2 — ★★</option><option value="1">1 — ★</option></select></label><label>${tx('report')}<textarea name="report_text" rows="2" maxlength="500"></textarea></label><button class="primary-button" type="submit">${tx('send')}</button></form>`;openModal(n.title,'VERIFIED STUDENT NOTE',html);$('#feedback-form').addEventListener('submit',async e=>{e.preventDefault();if(!me){authOpen();return;}const fd=new FormData(e.target);try{await api(`/notes/${encodeURIComponent(id)}`,{method:'POST',body:JSON.stringify({rating:Number(fd.get('rating')),report_text:fd.get('report_text')})});toast(lang==='bn'?'মতামত জমা হয়েছে।':'Feedback submitted.');closeModal();}catch(err){toast(err.message,true);}});}catch(e){toast(e.message,true);}}
  async function reviseNote(id){if(!me)return;try{const data=await api('/my/notes');const n=data.notes.find(x=>x.id===id);if(!n||n.status!=='changes_requested')return;openModal(lang==='bn'?'নোট সংশোধন করো':'Revise your note','REQUESTED CHANGES',`<p class="note-detail-desc">${esc(n.review_note||'Please make the requested corrections and resubmit.')}</p><form id="revise-form" data-note-id="${esc(n.id)}" class="modal-form"><label>${tx('noteTitle')}<input name="title" value="${esc(n.title)}" required maxlength="120"></label><div class="form-row"><label>${tx('subject')}<select name="subject">${subjects.map(s=>`<option ${s===n.subject?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>${tx('paper')}<input name="paper" value="${esc(n.paper||'')}" maxlength="40"></label></div><label>${tx('chapter')}<input name="chapter" value="${esc(n.chapter)}" required maxlength="100"></label><div class="form-row"><label>${tx('type')}<select name="note_type">${['Chapter Summary','Detailed Notes','Short Notes','Formula Sheet','Question Solution'].map(s=>`<option ${s===n.note_type?'selected':''}>${s}</option>`).join('')}</select></label><label>${tx('language')}<select name="content_language"><option value="bn" ${n.content_language==='bn'?'selected':''}>বাংলা</option><option value="en" ${n.content_language==='en'?'selected':''}>English</option></select></label></div><label>${tx('description')}<textarea name="description" rows="3" maxlength="500">${esc(n.description||'')}</textarea></label><label class="upload-box">${tx('file')}<small>${lang==='bn'?'নতুন ফাইল দিলে আগের ফাইলটি বদলে যাবে; না দিলে আগের ফাইল থাকবে।':'A new file replaces the previous one. Leave empty to keep the existing file.'}</small><input name="file" type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png"></label><label class="consent-row"><input type="checkbox" name="permission_agree" value="yes" required><span>${lang==='bn'?'আমি এই নোট বিনামূল্যে শেয়ার করার অধিকার নিশ্চিত করছি।':'I confirm I have the right to share this note for free.'}</span></label><button class="primary-button full-button" type="submit">${tx('submit')} →</button></form>`);}catch(e){toast(e.message,true);}}
  async function loadRequests(){try{const d=await api('/requests');$('#requests-total').textContent=d.requests.length;$('#request-list').innerHTML=d.requests.map(r=>`<div class="request-row"><span class="request-symbol">＋</span><div class="request-row-main"><b>${esc(r.title)}</b><p>${esc(r.details||'')}</p><small>${esc(r.subject)} · ${esc(r.class_name)} · ${esc(r.author_name)} · ${dateText(r.created_at)}</small></div></div>`).join('')||`<div class="empty-state">${tx('noRequests')}</div>`;}catch(e){toast(e.message,true);}}
  async function loadLeaderboard(){try{const d=await api('/leaderboard');$('#leaderboard-body').innerHTML=d.leaders.map((u,i)=>`<tr><td class="table-rank">${String(i+1).padStart(2,'0')}</td><td><b>${esc(u.display_name)}</b></td><td>${esc(u.class_name)} · ${esc(u.study_group)}</td><td>${u.contributions}</td><td><b>${u.exam_points}</b></td></tr>`).join('')||`<tr><td colspan="5">${tx('noResults')}</td></tr>`;}catch(e){toast(e.message,true);}}
  async function loadActivity(){if(!me){$('#activity-list').innerHTML=`<div class="empty-state">${tx('signFirst')}</div>`;$('#my-notes-list').innerHTML='';return;}try{const [a,n]=await Promise.all([api('/activity'),api('/my/notes')]);$('#activity-list').innerHTML=a.activity.map(x=>`<div class="request-row"><span class="request-symbol">${x.event_type==='exam_submitted'?'◷':'✦'}</span><div class="request-row-main"><b>${esc(x.description)}</b><small>${dateText(x.created_at)}</small></div></div>`).join('')||`<div class="empty-state">${tx('noActivity')}</div>`;$('#my-notes-list').innerHTML=n.notes.map(x=>`<div class="request-row"><span class="request-symbol">▤</span><div class="request-row-main"><b>${esc(x.title)}</b><small>${esc(x.subject)} · ${esc(x.chapter)} · ${tx(x.status)}</small>${x.review_note?`<p>${esc(x.review_note)}</p>`:''}${x.status==='changes_requested'?`<button class="note-open" data-revise="${esc(x.id)}">${lang==='bn'?'সংশোধন করে আবার জমা দাও':'Revise and resubmit'} →</button>`:''}</div></div>`).join('')||`<div class="empty-state">${tx('noNotes')}</div>`;$('#my-note-total').textContent=n.notes.length;$('#my-exam-total').textContent=a.activity.filter(x=>x.event_type==='exam_submitted').length;}catch(e){toast(e.message,true);}}
  async function loadFeedback(){if(!me)return;try{const d=await api('/feedback');$('#feedback-total').textContent=d.feedback.length;$('#feedback-nav-count').textContent=d.feedback.filter(x=>x.status==='open').length;$('#feedback-nav-count').classList.toggle('hidden',!d.feedback.some(x=>x.status==='open'));$('#feedback-list').innerHTML=d.feedback.map(x=>`<article class="request-row"><span class="request-symbol">${x.category==='feature'?'✦':x.category==='bug'?'!':x.category==='content'?'▤':'•'}</span><div class="request-row-main"><b>${esc(x.title)}</b><p>${esc(x.details)}</p><small>${dateText(x.created_at)} · ${({open:lang==='bn'?'পাঠানো হয়েছে': 'Submitted',under_review:lang==='bn'?'পর্যালোচনায়':'In review',done:lang==='bn'?'সম্পন্ন':'Completed',closed:lang==='bn'?'বন্ধ':'Closed'})[x.status]||x.status}</small></div></article>`).join('')||`<div class="empty-state">${lang==='bn'?'এখনো কোনো মতামত পাঠাওনি। তোমার প্রথম আইডিয়াটি শেয়ার করো।':'No feedback yet. Share your first idea.'}</div>`;}catch(e){toast(e.message,true);}}
  async function loadReview(){if(!me||!['admin','moderator'].includes(me.role))return;try{const [n,o,r,f]=await Promise.all([api('/admin/notes'),api('/admin/overview'),api('/admin/reports'),api('/admin/feedback')]);$('#review-pending').textContent=o.pending;$('#review-approved').textContent=o.approved;$('#review-students').textContent=o.students;$('#pending-count').textContent=o.pending;$('#report-list').innerHTML=r.reports.map(x=>`<article class="review-row"><span class="review-file">!</span><div class="review-main"><b>${esc(x.note_title)}</b><small>${esc(x.subject)} · ${esc(x.reporter||'Student')} · ${dateText(x.created_at)}</small><small>${esc(x.report_text)}</small></div></article>`).join('')||`<div class="empty-state">${lang==='bn'?'কোনো রিপোর্ট নেই।':'No reports yet.'}</div>`;$('#review-list').innerHTML=n.notes.map(x=>`<article class="review-row"><span class="review-file">${x.file_mime==='application/pdf'?'PDF':'NOTE'}</span><div class="review-main"><b>${esc(x.title)}</b><small>${esc(x.author_name)} · ${esc(x.subject)} · ${esc(x.class_name)} / ${esc(x.study_group)} · ${esc(x.chapter)}</small><small>${esc(x.file_name||'No file')} · ${dateText(x.created_at)}</small>${x.file_id?`<a class="file-open" target="_blank" rel="noopener" href="${API}/files/${encodeURIComponent(x.file_id)}">Open attachment</a>`:''}</div><div class="review-actions"><button class="reject-btn" data-review="rejected" data-id="${esc(x.id)}">${tx('reject')}</button><button class="reject-btn" data-review="changes_requested" data-id="${esc(x.id)}">${tx('needsChanges')}</button><button class="approve-btn" data-review="approved" data-id="${esc(x.id)}">${tx('approve')}</button></div></article>`).join('')||`<div class="empty-state">${tx('noPending')}</div>`;$('#admin-feedback-list').innerHTML=f.feedback.map(x=>`<article class="review-row feedback-review-row"><span class="review-file">${x.category==='feature'?'IDEA':x.category==='bug'?'BUG':x.category==='content'?'NOTE':'OTHER'}</span><div class="review-main"><b>${esc(x.title)}</b><small>${esc(x.display_name)} · ${esc(x.email)} · ${esc(x.class_name)} / ${esc(x.study_group)} · ${dateText(x.created_at)}</small><small>${esc(x.details)}</small><small class="feedback-status">${esc(x.status)}</small></div><div class="review-actions">${x.status==='open'?`<button class="reject-btn" data-feedback-status="under_review" data-id="${esc(x.id)}">Review</button>`:''}${x.status!=='done'?`<button class="approve-btn" data-feedback-status="done" data-id="${esc(x.id)}">Done</button>`:''}</div></article>`).join('')||`<div class="empty-state">${lang==='bn'?'নতুন কোনো মতামত নেই।':'No student feedback yet.'}</div>`;}catch(e){toast(e.message,true);}}
  const profileAvatar=(p,size='large')=>p.avatar_url?`<img class="profile-avatar ${size}" src="${esc(p.avatar_url)}" alt="${esc(p.display_name)} profile picture">`:`<span class="profile-avatar ${size} fallback-avatar">${esc(initials(p.display_name))}</span>`;
  async function openPublicProfile(memberNo){try{await changePage('profile');const d=await api(`/profile/${encodeURIComponent(memberNo)}`);renderProfilePage(d.profile,false);}catch(e){toast(e.message,true);}}
  async function loadMyProfilePage(){if(!me)return;try{const d=await api('/profile/me');renderProfilePage(d.profile,true);}catch(e){toast(e.message,true);}}
  function renderProfilePage(p,isOwn){const dob=p.date_of_birth?dateText(p.date_of_birth):'';$('#profile-edit-open').classList.toggle('hidden',!isOwn);$('#profile-view-content').innerHTML=`<article class="member-profile-card">${profileAvatar(p,'hero')}<div class="member-profile-main"><div class="member-profile-title"><div><div class="eyebrow">AJZIO MEMBER PROFILE</div><h2>${esc(p.display_name)}</h2><span class="member-number">#${esc(p.member_no)}</span></div>${isOwn?'<span class="profile-role-lock">✦ '+esc(tx(p.role))+'</span>':`<span class="profile-role-lock">${esc(tx(p.role))}</span>`}</div><p class="member-bio">${esc(p.bio||((lang==='bn'?'এখনো কোনো Bio যোগ করা হয়নি।':'No bio added yet.')))}</p><div class="public-profile-meta"><span>${esc(p.class_name)}</span><span>${esc(p.study_group)}</span><span>${esc(p.education_board||'')}</span></div><div class="profile-facts">${dob?`<span>🎂 ${lang==='bn'?'জন্মতারিখ':'Date of birth'}: ${esc(dob)}</span>`:''}<span>${lang==='bn'?'যোগ দিয়েছেন':'Joined'}: ${dateText(p.created_at)}</span></div>${isOwn?`<p class="profile-privacy-note">${lang==='bn'?'জন্মতারিখ ডিফল্টভাবে ব্যক্তিগত থাকে। Edit Profile থেকে চাইলে দেখাতে পারো।':'Your date of birth is private by default. You can choose to display it in Edit Profile.'}</p>`:''}</div></article>`;}
  async function loadChat(){if(!me)return;try{const d=await api('/chat');$('#chat-messages').innerHTML=d.messages.map(m=>`<article class="chat-message" id="message-${esc(m.id)}"><button class="chat-avatar-button" data-member="${esc(m.member_no)}">${m.avatar_url?`<img class="chat-avatar-image" src="${esc(m.avatar_url)}" alt="">`:`<span class="chat-avatar">${esc(initials(m.display_name))}</span>`}</button><div class="chat-message-body"><div class="chat-message-meta"><button class="chat-author-link" data-member="${esc(m.member_no)}">${esc(m.display_name)}</button><button class="member-chip" data-member="${esc(m.member_no)}">#${esc(m.member_no)}</button><small>${new Date(m.created_at).toLocaleTimeString(lang==='bn'?'bn-BD':'en-GB',{hour:'2-digit',minute:'2-digit'})}</small>${m.tagged_admin?'<span class="chat-tag">@admin</span>':''}</div>${m.reply_to_id?`<div class="reply-reference"><small>↳ ${esc(m.reply_display_name||'Reply')} · #${esc(m.reply_member_no||'')}</small><span>${esc((m.reply_message||'').slice(0,130))}</span></div>`:''}<div class="chat-message-text">${esc(m.message)}</div>${m.mentions?.length?`<div class="message-mentions">${m.mentions.map(x=>`<span>@${esc(x.target_type==='role'?x.target_value:'#'+x.target_value)}</span>`).join('')}</div>`:''}<div class="chat-message-actions"><button class="chat-reply-button" data-chat-reply="${esc(m.id)}" data-reply-name="${esc(m.display_name)}" data-reply-text="${esc(m.message.slice(0,120))}">↩ ${lang==='bn'?'উত্তর':'Reply'}</button>${m.member_no!==me.member_no?`<button class="chat-report-button" data-chat-report="${esc(m.id)}">⚑ ${lang==='bn'?'রিপোর্ট':'Report'}</button>`:''}</div></div></article>`).join('')||`<div class="empty-state">${lang==='bn'?'এখনো কোনো মেসেজ নেই। পড়াশোনা নিয়ে প্রথম প্রশ্নটি করো!':'No messages yet. Start with a study question!'}</div>`;$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;}catch(e){if(e.status!==423)toast(e.message,true);}}
  async function loadAdminPanel(){if(!me||me.role!=='admin')return;try{const [u,a,c,r,m,au]=await Promise.all([api('/admin/users'),api('/admin/appeals'),api('/admin/chat'),api('/admin/chat-reports'),api('/admin/moderation'),api('/admin/audit')]);adminUsersCache=u.users;renderAdminUsers();$('#appeal-count').textContent=a.appeals.filter(x=>x.status==='pending').length;$('#admin-appeals-list').innerHTML=a.appeals.map(x=>`<article class="admin-row"><div class="admin-row-head"><b>#${esc(x.member_no)} · ${esc(x.display_name)}</b><span class="admin-status ${esc(x.status)}">${esc(x.status)}</span></div><small>${esc(x.email)} · ${dateText(x.created_at)}</small><p>${esc(x.details)}</p>${x.admin_response?`<small>Admin: ${esc(x.admin_response)}</small>`:''}${x.status==='pending'?`<div class="admin-actions"><button data-appeal-action="approve" data-id="${esc(x.id)}">Approve & unlock</button><button class="danger-action" data-appeal-action="decline" data-id="${esc(x.id)}">Decline</button></div>`:''}</article>`).join('')||`<div class="admin-empty">কোনো আপিল নেই।</div>`;$('#admin-chat-list').innerHTML=c.messages.map(x=>`<article class="admin-row"><div class="admin-row-head"><button class="admin-profile-link" data-member="${esc(x.member_no)}">#${esc(x.member_no)} · ${esc(x.display_name)}</button><span class="chat-tag">@admin mentioned</span></div><small>${dateText(x.created_at)}</small><p>${esc(x.message)}</p><div class="admin-actions"><button class="danger-action" data-chat-delete="${esc(x.id)}">Delete message</button></div></article>`).join('')||`<div class="admin-empty">কোনো Admin mention নেই।</div>`;$('#admin-chat-reports').innerHTML=r.reports.map(x=>`<article class="admin-row"><div class="admin-row-head"><button class="admin-profile-link" data-member="${esc(x.member_no)}">Reported by #${esc(x.member_no)} · ${esc(x.reporter)}</button><span class="admin-status ${esc(x.status)}">${esc(x.status)}</span></div><small>Message by <button class="admin-profile-link inline" data-member="${esc(x.message_member_no)}">#${esc(x.message_member_no)} · ${esc(x.message_author)}</button> · ${dateText(x.created_at)}</small><p>${esc(x.reason)}</p><blockquote>${esc(x.message)}</blockquote>${x.status==='open'?`<div class="admin-actions"><button data-report-action="reviewed" data-id="${esc(x.id)}">Mark reviewed</button><button data-report-action="dismissed" data-id="${esc(x.id)}">Dismiss</button><button class="danger-action" data-chat-delete="${esc(x.message_id)}">Delete message</button></div>`:''}</article>`).join('')||`<div class="admin-empty">কোনো চ্যাট রিপোর্ট নেই।</div>`;$('#admin-moderation-list').innerHTML=m.events.map(x=>`<article class="admin-row"><b>#${esc(x.member_no)} · ${esc(x.display_name)}</b><small>${esc(x.violation_type.replaceAll('_',' '))} · ${esc(x.action)} · ${dateText(x.created_at)}</small></article>`).join('')||`<div class="admin-empty">কোনো মডারেশন ইভেন্ট নেই।</div>`;$('#admin-audit-list').innerHTML=au.events.map(x=>`<article class="admin-row"><b>#${esc(x.admin_member_no)} · ${esc(x.admin_name)} — ${esc(x.action.replaceAll('_',' '))}</b><small>${esc(x.target_type)} · ${esc(x.target_id)} · ${dateText(x.created_at)}</small>${x.details?`<p>${esc(x.details)}</p>`:''}</article>`).join('')||`<div class="admin-empty">এখনো কোনো admin action নেই।</div>`;const alerts=a.appeals.filter(x=>x.status==='pending').length+c.messages.filter(x=>x.tagged_admin).length+r.reports.filter(x=>x.status==='open').length;$('#admin-alert-count').textContent=alerts;}catch(e){toast(e.message,true);}}
  function renderAdminUsers(){const q=($('#admin-user-search')?.value||'').trim().toLowerCase();const list=adminUsersCache.filter(x=>!q||String(x.member_no).includes(q)||x.display_name.toLowerCase().includes(q)||x.email.toLowerCase().includes(q));$('#admin-users-list').innerHTML=list.map(x=>`<article class="admin-row"><div class="admin-row-head"><button class="admin-profile-link" data-member="${esc(x.member_no)}">#${esc(x.member_no)} · ${esc(x.display_name)}</button><span class="admin-status ${esc(x.account_status)}">${esc(x.account_status)}</span></div><small>${esc(x.email)} · ${esc(x.class_name)} · ${esc(x.study_group)} · ${esc(x.role)}</small><small>${x.suspended_until?`Until ${esc(new Date(x.suspended_until).toLocaleString())}`:esc(x.restriction_reason||'Active account')}</small>${x.role!=='admin'?`<div class="admin-actions">${x.account_status==='active'?`<button data-user-action="suspend" data-hours="6" data-id="${esc(x.id)}">Suspend 6h</button><button data-user-action="suspend" data-hours="24" data-id="${esc(x.id)}">Suspend 24h</button><button class="danger-action" data-user-action="lock" data-id="${esc(x.id)}">Lock account</button>`:`<button data-user-action="unlock" data-id="${esc(x.id)}">Restore access</button>`}</div>`:'<small>Administrator account · protected</small>'}</article>`).join('')||`<div class="admin-empty">কোনো শিক্ষার্থী পাওয়া যায়নি।</div>`;}
