    const feedbackStatus=e.target.closest('[data-feedback-status]');if(feedbackStatus){api('/admin/feedback',{method:'POST',body:JSON.stringify({feedback_id:feedbackStatus.dataset.id,status:feedbackStatus.dataset.feedbackStatus})}).then(()=>{toast(tx('success'));loadReview();}).catch(err=>toast(err.message,true));}
    const authTab=e.target.closest('[data-auth-tab]');if(authTab){authOpen(authTab.dataset.authTab);return;}
    if(e.target.closest('#google-auth-btn')&&googleEnabled){window.location.href='/auth/google/start';}
    if(e.target.closest('#survey-skip')){closeModal();toast(lang==='bn'?'পরে উত্তর দিতে পারবে।':'You can answer later.');}
    const member=e.target.closest('[data-member]');if(member){openPublicProfile(member.dataset.member);return;}
    const reply=e.target.closest('[data-chat-reply]');if(reply){pendingChatReply={id:reply.dataset.chatReply,name:reply.dataset.replyName,text:reply.dataset.replyText};$('#chat-reply-preview').innerHTML=`<span>↩ ${lang==='bn'?'উত্তর দিচ্ছ':'Replying to'} <b>${esc(pendingChatReply.name)}</b>: ${esc(pendingChatReply.text)}</span><button type="button" id="chat-reply-cancel">×</button>`;$('#chat-reply-preview').classList.remove('hidden');$('#chat-message-input').focus();return;}
    if(e.target.closest('#chat-reply-cancel')){pendingChatReply=null;$('#chat-reply-preview').classList.add('hidden');return;}
    const reportAction=e.target.closest('[data-report-action]');if(reportAction){api('/admin/chat-reports/action',{method:'POST',body:JSON.stringify({report_id:reportAction.dataset.id,decision:reportAction.dataset.reportAction})}).then(()=>{toast('Report updated.');loadAdminPanel();}).catch(err=>toast(err.message,true));return;}
    const chatReport=e.target.closest('[data-chat-report]');if(chatReport){reportChatMessage(chatReport.dataset.chatReport);return;}
    if(e.target.closest('#chat-refresh'))loadChat();if(e.target.closest('#admin-refresh'))loadAdminPanel();
    const userAction=e.target.closest('[data-user-action]');if(userAction){const reason=prompt(lang==='bn'?'কারণ লিখো (ঐচ্ছিক):':'Reason (optional):')||'';api('/admin/users/action',{method:'POST',body:JSON.stringify({user_id:userAction.dataset.id,action:userAction.dataset.userAction,hours:Number(userAction.dataset.hours||6),reason})}).then(()=>{toast('Account updated.');loadAdminPanel();}).catch(err=>toast(err.message,true));}
    const appealAction=e.target.closest('[data-appeal-action]');if(appealAction){const response=prompt(lang==='bn'?'শিক্ষার্থীর জন্য অ্যাডমিনের উত্তর (ঐচ্ছিক):':'Admin response to student (optional):')||'';api('/admin/appeals/action',{method:'POST',body:JSON.stringify({appeal_id:appealAction.dataset.id,decision:appealAction.dataset.appealAction,response})}).then(()=>{toast('Appeal updated.');loadAdminPanel();}).catch(err=>toast(err.message,true));}
    const chatDelete=e.target.closest('[data-chat-delete]');if(chatDelete&&confirm('Delete this community message?'))api('/admin/chat/delete',{method:'POST',body:JSON.stringify({message_id:chatDelete.dataset.chatDelete})}).then(()=>loadAdminPanel()).catch(err=>toast(err.message,true));
    if(e.target.closest('#restriction-logout'))api('/auth/logout',{method:'POST',body:'{}'}).then(()=>{me=null;$('#restriction-gate').classList.add('hidden');showAuthGate();authOpen('login');}).catch(err=>toast(err.message,true));
